class Solution:
    def simpleGraphExists(self, degrees: List[int]) -> bool:
        import bisect
        n = len(degrees)
        a = sorted(degrees)
        if sum(a) % 2:
            return False
        P = [0] * (n + 1)
        for i, x in enumerate(a):
            P[i + 1] = P[i] + x
        for k in range(1, n + 1):
            lhs = P[n] - P[n - k]
            j = bisect.bisect_right(a, k, 0, n - k)
            rhs = k * (k - 1) + k * ((n - k) - j) + P[j]
            if lhs > rhs:
                return False
        return True

