class Solution {
    public boolean simpleGraphExists(int[] degrees) {
        int n = degrees.length;
        int[] a = degrees.clone();
        Arrays.sort(a);
        long total = 0;
        for (int x : a) total += x;
        if (total % 2 != 0) return false;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + a[i];
        for (int k = 1; k <= n; k++) {
            long lhs = P[n] - P[n - k];
            int j = upperBound(a, k, n - k);
            long rhs = (long) k * (k - 1) + (long) k * ((n - k) - j) + P[j];
            if (lhs > rhs) return false;
        }
        return true;
    }
    private int upperBound(int[] a, int key, int hi) {
        int lo = 0;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] <= key) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

