class Solution:
    def simpleGraphExists(self, degrees: List[int]) -> bool:
        import heapq
        if sum(degrees) % 2:
            return False
        h = [-d for d in degrees]
        heapq.heapify(h)
        while h:
            d = -heapq.heappop(h)
            if d > len(h):
                return False
            tmp = []
            for _ in range(d):
                x = -heapq.heappop(h) - 1
                if x < 0:
                    return False
                tmp.append(-x)
            for x in tmp:
                heapq.heappush(h, x)
        return True

