class Solution {
public:
    bool simpleGraphExists(vector<int>& degrees) {
        if (accumulate(degrees.begin(), degrees.end(), 0LL) % 2) return false;
        priority_queue<int> h(degrees.begin(), degrees.end());
        while (!h.empty()) {
            int d = h.top(); h.pop();
            if (d > (int)h.size()) return false;
            vector<int> tmp;
            for (int i = 0; i < d; i++) {
                int x = h.top() - 1; h.pop();
                if (x < 0) return false;
                tmp.push_back(x);
            }
            for (int x : tmp) h.push(x);
        }
        return true;
    }
};

