class Solution {
    public boolean simpleGraphExists(int[] degrees) {
        long sum = 0;
        for (int x : degrees) sum += x;
        if (sum % 2 != 0) return false;
        PriorityQueue<Integer> h = new PriorityQueue<>(Collections.reverseOrder());
        for (int x : degrees) h.offer(x);
        while (!h.isEmpty()) {
            int d = h.poll();
            if (d > h.size()) return false;
            List<Integer> tmp = new ArrayList<>();
            for (int i = 0; i < d; i++) {
                int x = h.poll() - 1;
                if (x < 0) return false;
                tmp.add(x);
            }
            for (int x : tmp) h.offer(x);
        }
        return true;
    }
}

