var simpleGraphExists = function(degrees) {
    if (degrees.reduce((s, x) => s + x, 0) % 2) return false;
    const h = [...degrees];
    const pop = () => { const m = Math.max(...h); h.splice(h.indexOf(m), 1); return m; };
    while (h.length) {
        const d = pop();
        if (d > h.length) return false;
        const tmp = [];
        for (let i = 0; i < d; i++) {
            const x = pop() - 1;
            if (x < 0) return false;
            tmp.push(x);
        }
        h.push(...tmp);
    }
    return true;
};
